query.base:
TS metrics-gcp.compute.otel-*
// Compute Engine VM instances only
| WHERE resource.attributes.gcp.resource_type == "gce_instance"
// Queue depth and latency are GAUGEs keyed by device. instance_name is NOT a dimension of these series,
// so disks are identified by instance_id + device_name.
| STATS
    queue_depth = AVG(AVG_OVER_TIME(`compute.googleapis.com/instance/disk/average_io_queue_depth`)),
    latency_us = AVG(AVG_OVER_TIME(`compute.googleapis.com/instance/disk/average_io_latency`))
  BY resource.attributes.project_id, resource.attributes.zone, resource.attributes.instance_id, attributes.device_name, attributes.storage_type

breach.segment:
WHERE queue_depth IS NOT NULL AND latency_us IS NOT NULL
| EVAL latency_ms = ROUND(latency_us / 1000.0, 2), queue_depth = ROUND(queue_depth, 2)
// Latency threshold (ms) per storage type: HDD-backed pd-standard is naturally slower.
// Adjust per disk type as needed (for example add a branch for hyperdisk-* types).
| EVAL latency_threshold_ms = CASE(attributes.storage_type == "pd-standard", 50.0, 10.0)
// Breach: deep queue AND slow I/O. A deep queue with fast I/O is a healthy throughput workload.
| WHERE queue_depth >= 8 AND latency_ms >= latency_threshold_ms
| KEEP resource.attributes.project_id, resource.attributes.zone, resource.attributes.instance_id, attributes.device_name, attributes.storage_type, queue_depth, latency_ms, latency_threshold_ms
| SORT queue_depth DESC
| LIMIT 100
